sql.q1:
```sql
SELECT COUNT(*) FROM issues WHERE state = 'open' AND (title LIKE '%security%' OR body LIKE '%security%');
```

sql.q2:
```sql
SELECT COUNT(*) FROM issues WHERE is_pr = 1;
```

sql.q3:
```sql
SELECT SUM(comments) FROM issues WHERE state = 'closed';
```

sql.q4:
```sql
SELECT user, COUNT(*) AS n FROM issues WHERE is_pr = 1 GROUP BY user ORDER BY n DESC LIMIT 1;
```

sql.q5:
```sql
SELECT number FROM issues WHERE state = 'open' AND is_pr = 0 AND comments > 5 ORDER BY number;
```

sql.q6:
```sql
SELECT COUNT(DISTINCT j.value) FROM issues, json_each(issues.labels) AS j;
```

sql.q8:
```sql
SELECT COUNT(*) FROM (SELECT user FROM issues WHERE is_pr = 1 INTERSECT SELECT user FROM issues WHERE is_pr = 0);
```

sql.q9:
```sql
SELECT printf('%.2f', AVG(comments)) FROM issues WHERE state = 'open' AND is_pr = 0;
```

sql.q10:
```sql
SELECT COUNT(*) FROM issues WHERE state = 'open' AND EXISTS (SELECT 1 FROM json_each(issues.labels) AS j WHERE j.value = 'bug');
```
